const express=require('express');
const session=require('express-session');
const bcrypt=require('bcryptjs');
const Database=require('better-sqlite3');
const multer=require('multer');
const path=require('path');
const fs=require('fs');
const crypto=require('crypto');

const app=express();
const PORT=Number(process.env.PORT)||3000;
app.set('trust proxy', 1);
const ROOT=__dirname;
const DATA=process.env.LIWEETAX_DATA_DIR || path.join(ROOT,'data');
const UPLOADS=process.env.LIWEETAX_UPLOADS_DIR || path.join(ROOT,'uploads');
fs.mkdirSync(DATA,{recursive:true});fs.mkdirSync(UPLOADS,{recursive:true});
const db=new Database(path.join(DATA,'liweeitax.db'));

// Production safety: Render should provide a stable secret via env.
if (process.env.NODE_ENV==='production' && !process.env.SESSION_SECRET) {
  console.warn('SESSION_SECRET is not set; configure it in Render Environment Variables.');
}

db.pragma('journal_mode = WAL');
db.pragma('foreign_keys = ON');
try { db.exec("ALTER TABLE users ADD COLUMN verification_label TEXT DEFAULT 'Verified account'"); } catch(e) {}

db.exec(`
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT UNIQUE NOT NULL,password TEXT NOT NULL,bio TEXT DEFAULT '',avatar TEXT DEFAULT '',cover TEXT DEFAULT '',website TEXT DEFAULT '',private INTEGER DEFAULT 0,verified INTEGER DEFAULT 0,level INTEGER DEFAULT 1,xp INTEGER DEFAULT 0,streak INTEGER DEFAULT 0,verification_label TEXT DEFAULT 'Verified account',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS posts(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,content TEXT,media TEXT,media_type TEXT DEFAULT '',music TEXT DEFAULT '',views INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS likes(user_id INTEGER,post_id INTEGER,UNIQUE(user_id,post_id));
CREATE TABLE IF NOT EXISTS saves(user_id INTEGER,post_id INTEGER,UNIQUE(user_id,post_id));
CREATE TABLE IF NOT EXISTS follows(follower_id INTEGER,following_id INTEGER,UNIQUE(follower_id,following_id));
CREATE TABLE IF NOT EXISTS comments(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,post_id INTEGER,parent_id INTEGER,content TEXT,pinned INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS profile_stickers(id INTEGER PRIMARY KEY AUTOINCREMENT,owner_id INTEGER,sender_id INTEGER,sticker TEXT NOT NULL,verification_label TEXT DEFAULT 'Verified account',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY AUTOINCREMENT,sender_id INTEGER,receiver_id INTEGER,content TEXT,media TEXT,seen INTEGER DEFAULT 0,verification_label TEXT DEFAULT 'Verified account',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,type TEXT,text TEXT,read INTEGER DEFAULT 0,verification_label TEXT DEFAULT 'Verified account',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reports(id INTEGER PRIMARY KEY AUTOINCREMENT,reporter_id INTEGER,target_type TEXT,target_id INTEGER,reason TEXT,verification_label TEXT DEFAULT 'Verified account',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS drafts(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,content TEXT,media TEXT,music TEXT,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS blocks(blocker_id INTEGER,blocked_id INTEGER,UNIQUE(blocker_id,blocked_id));
CREATE TABLE IF NOT EXISTS mutes(muter_id INTEGER,muted_id INTEGER,UNIQUE(muter_id,muted_id));
CREATE TABLE IF NOT EXISTS chat_streaks(user_a INTEGER,user_b INTEGER,streak INTEGER DEFAULT 0,last_day TEXT,UNIQUE(user_a,user_b));
CREATE TABLE IF NOT EXISTS post_reactions(user_id INTEGER,post_id INTEGER,reaction TEXT NOT NULL,UNIQUE(user_id,post_id));
CREATE TABLE IF NOT EXISTS reposts(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,post_id INTEGER,quote TEXT DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,post_id));
CREATE TABLE IF NOT EXISTS hashtags(id INTEGER PRIMARY KEY AUTOINCREMENT,tag TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS post_hashtags(post_id INTEGER,hashtag_id INTEGER,UNIQUE(post_id,hashtag_id));
CREATE TABLE IF NOT EXISTS stories(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,media TEXT,content TEXT,expires_at TEXT NOT NULL,verification_label TEXT DEFAULT 'Verified account',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS story_views(story_id INTEGER,user_id INTEGER,UNIQUE(story_id,user_id));
CREATE TABLE IF NOT EXISTS bookmarks_collections(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS collection_items(collection_id INTEGER,post_id INTEGER,UNIQUE(collection_id,post_id));
CREATE TABLE IF NOT EXISTS verification_requests(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER UNIQUE,status TEXT DEFAULT 'pending',note TEXT DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS post_views(id INTEGER PRIMARY KEY AUTOINCREMENT,post_id INTEGER,user_id INTEGER,session_key TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_settings(user_id INTEGER PRIMARY KEY,language TEXT DEFAULT 'en',theme TEXT DEFAULT 'dark',data_saver INTEGER DEFAULT 0,autoplay INTEGER DEFAULT 1,online_status INTEGER DEFAULT 1,read_receipts INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS post_polls(id INTEGER PRIMARY KEY AUTOINCREMENT,post_id INTEGER UNIQUE NOT NULL,question TEXT NOT NULL,options_json TEXT NOT NULL,expires_at TEXT,FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS poll_votes(poll_id INTEGER,user_id INTEGER,option_index INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(poll_id,user_id));
CREATE TABLE IF NOT EXISTS mentions(id INTEGER PRIMARY KEY AUTOINCREMENT,post_id INTEGER,comment_id INTEGER,mentioned_user_id INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS scheduled_posts(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,content TEXT,media TEXT,media_type TEXT DEFAULT '',music TEXT DEFAULT '',publish_at TEXT NOT NULL,status TEXT DEFAULT 'scheduled',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notification_preferences(user_id INTEGER PRIMARY KEY,likes INTEGER DEFAULT 1,comments INTEGER DEFAULT 1,follows INTEGER DEFAULT 1,messages INTEGER DEFAULT 1,mentions INTEGER DEFAULT 1,stories INTEGER DEFAULT 1,reposts INTEGER DEFAULT 1,streaks INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS hidden_words(user_id INTEGER,word TEXT,UNIQUE(user_id,word));
CREATE TABLE IF NOT EXISTS post_reports(id INTEGER PRIMARY KEY AUTOINCREMENT,post_id INTEGER,reporter_id INTEGER,reason TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS feature_usage(user_id INTEGER,feature_key TEXT,count INTEGER DEFAULT 0,last_used TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,feature_key));
CREATE INDEX IF NOT EXISTS idx_posts_created ON posts(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_posts_user ON posts(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_comments_post ON comments(post_id,created_at);
CREATE INDEX IF NOT EXISTS idx_messages_pair ON messages(sender_id,receiver_id,created_at);
CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id,read,created_at);
CREATE INDEX IF NOT EXISTS idx_follows_following ON follows(following_id);


`);

app.disable('x-powered-by');
app.set('trust proxy', 1);
app.use(express.json({limit:'2mb'}));
app.use(express.urlencoded({extended:true,limit:'2mb'}));
const sessionSecret=process.env.SESSION_SECRET || crypto.createHash('sha256').update('liweeitax-development-only-secret').digest('hex');
app.use(session({name:'liweeitax.sid',secret:sessionSecret,resave:false,saveUninitialized:false,cookie:{httpOnly:true,sameSite:'lax',secure:process.env.NODE_ENV==='production',maxAge:1000*60*60*24*30}}));
app.use('/uploads',express.static(UPLOADS,{maxAge:'7d'}));
app.use(express.static(path.join(ROOT,'public')));

const upload=multer({storage:multer.diskStorage({destination:UPLOADS,filename:(req,file,cb)=>cb(null,Date.now()+'-'+crypto.randomBytes(6).toString('hex')+path.extname(file.originalname).toLowerCase())})});
const auth=(req,res,next)=>req.session.userId?next():res.status(401).json({error:'Login required'});
const cleanText=(v,max=1000)=>String(v??'').trim().slice(0,max);
const safeUser=u=>u&&({id:u.id,username:u.username,bio:u.bio,avatar:u.avatar,cover:u.cover,website:u.website,private:!!u.private,verified:!!u.verified,verification_label:u.verification_label||'Verified account',level:u.level,xp:u.xp,streak:u.streak,created_at:u.created_at});
const notify=(userId,type,text)=>{if(userId)db.prepare('INSERT INTO notifications(user_id,type,text) VALUES(?,?,?)').run(userId,type,text)};
const isBlocked=(a,b)=>!!db.prepare('SELECT 1 FROM blocks WHERE blocker_id=? AND blocked_id=?').get(a,b);
const dayKey=()=>new Date().toISOString().slice(0,10);
const pair=(a,b)=>a<b?[a,b]:[b,a];
function updateChatStreak(a,b){const [x,y]=pair(a,b),today=dayKey();let r=db.prepare('SELECT * FROM chat_streaks WHERE user_a=? AND user_b=?').get(x,y);if(!r){db.prepare('INSERT INTO chat_streaks(user_a,user_b,streak,last_day) VALUES(?,?,1,?)').run(x,y,today);return 1}if(r.last_day===today)return r.streak;const prev=new Date(Date.now()-86400000).toISOString().slice(0,10);const streak=r.last_day===prev?r.streak+1:1;db.prepare('UPDATE chat_streaks SET streak=?,last_day=? WHERE user_a=? AND user_b=?').run(streak,today,x,y);return streak}
function extractTags(text){return [...new Set(((String(text||'').match(/#[A-Za-z0-9_]+/g))||[]).map(x=>x.slice(1).toLowerCase()))].slice(0,20)}
function syncHashtags(postId,text){for(const tag of extractTags(text)){db.prepare('INSERT OR IGNORE INTO hashtags(tag) VALUES(?)').run(tag);const h=db.prepare('SELECT id FROM hashtags WHERE tag=?').get(tag);db.prepare('INSERT OR IGNORE INTO post_hashtags(post_id,hashtag_id) VALUES(?,?)').run(postId,h.id)}}



function seedStarterContent(){
  const count=db.prepare('SELECT count(*) c FROM posts').get().c;
  const verifiedUsers=[
    ['liweeitax','Official Liweeitax account'],
    ['liwee_music','Music & edits creator'],
    ['liwee_daily','Daily community account']
  ];
  const ids=[];
  for(const [username,bio] of verifiedUsers){
    let u=db.prepare('SELECT * FROM users WHERE lower(username)=lower(?)').get(username);
    if(!u){const hash=bcrypt.hashSync(crypto.randomBytes(18).toString('hex'),12);const r=db.prepare('INSERT INTO users(username,password,bio,verified,verification_label) VALUES(?,?,?,?,?)').run(username,hash,bio,1,'Verified account');u=db.prepare('SELECT * FROM users WHERE id=?').get(r.lastInsertRowid)}
    else if(!u.verified) db.prepare("UPDATE users SET verified=1,verification_label='Verified account' WHERE id=?").run(u.id);
    ids.push(u.id);
  }
  if(count===0){
    const posts=[
      [ids[0],'Welcome to Liweeitax ✦ A social space for creators, music, photos and short videos. #liweeitax #welcome'],
      [ids[1],'Drop your favorite track or edit below 🎧✨ #music #edits #y2k'],
      [ids[2],'What are you posting today? 📸🎬 #community #reels'],
      [ids[0],'Save your favorite videos for offline viewing with the new Offline Mode 📴 #offline'],
      [ids[1],'Creator tip: keep your captions clear and your community respectful 💙 #creator'],
      [ids[2],'Explore trending posts, follow creators and build your own profile 🚀 #explore']
    ];
    const ins=db.prepare('INSERT INTO posts(user_id,content,media,media_type,music) VALUES(?,?,?,?,?)');
    for(const [uid,content] of posts){const r=ins.run(uid,content,'','','');syncHashtags(r.lastInsertRowid,content)}
  }
}
seedStarterContent();

// Lightweight per-IP write throttle; protects accidental spam without needing another package.
const buckets=new Map();
app.use('/api',(req,res,next)=>{if(!['POST','PUT','PATCH','DELETE'].includes(req.method))return next();const key=(req.ip||'x')+':'+Math.floor(Date.now()/10000);const n=(buckets.get(key)||0)+1;buckets.set(key,n);if(n>35)return res.status(429).json({error:'Too many requests. Try again shortly.'});next()});


app.get('/api/username-available',(req,res)=>{const username=cleanText(req.query.username,30).replace(/^@/,'');if(!/^[A-Za-z0-9_.-]{3,30}$/.test(username))return res.json({available:false,reason:'Invalid username'});res.json({available:!db.prepare('SELECT id FROM users WHERE lower(username)=lower(?)').get(username)});});
app.get('/api/verification-status',auth,(req,res)=>res.json(db.prepare('SELECT * FROM verification_requests WHERE user_id=?').get(req.session.userId)||{status:'none'}));
app.post('/api/verification-request',auth,(req,res)=>{const note=cleanText(req.body.note,500);const existing=db.prepare('SELECT * FROM verification_requests WHERE user_id=?').get(req.session.userId);if(existing&&existing.status==='pending')return res.status(409).json({error:'Verification request already pending'});db.prepare("INSERT INTO verification_requests(user_id,status,note) VALUES(?,?,?) ON CONFLICT(user_id) DO UPDATE SET status='pending',note=excluded.note,created_at=CURRENT_TIMESTAMP").run(req.session.userId,'pending',note);res.json({ok:true,status:'pending'});});
app.get('/api/health',(req,res)=>res.status(200).json({ok:true,service:'liweeitax',time:new Date().toISOString(),database:!!db.prepare('SELECT 1').get()}));

app.get('/api/me',(req,res)=>{res.set('Cache-Control','no-store');const u=req.session&&req.session.userId?db.prepare('SELECT * FROM users WHERE id=?').get(req.session.userId):null;res.json({user:safeUser(u)||null})});
function establishSession(req,res,userId,cb){req.session.regenerate(err=>{if(err)return cb(err);req.session.userId=userId;req.session.save(cb);});}
app.post('/api/register',(req,res)=>{let username=cleanText(req.body.username,30).replace(/^@/,'');const password=String(req.body.password||'');if(!/^[A-Za-z0-9_.-]{3,30}$/.test(username))return res.status(400).json({error:'Username must be 3-30 characters: letters, numbers, _, ., -'});if(password.length<6)return res.status(400).json({error:'Password must be at least 6 characters'});if(db.prepare('SELECT id FROM users WHERE lower(username)=lower(?)').get(username))return res.status(409).json({error:'Username already exists'});try{const hash=bcrypt.hashSync(password,12);const r=db.prepare('INSERT INTO users(username,password) VALUES(?,?)').run(username,hash);establishSession(req,res,r.lastInsertRowid,err=>err?res.status(500).json({error:'Could not create session'}):res.json({ok:true,user:safeUser(db.prepare('SELECT * FROM users WHERE id=?').get(r.lastInsertRowid))}));}catch(e){if(String(e.message).includes('UNIQUE'))return res.status(409).json({error:'Username already exists'});res.status(500).json({error:'Registration failed'});}});
app.post('/api/login',(req,res)=>{const username=cleanText(req.body.username,30).replace(/^@/,'');const password=String(req.body.password||'');if(!username||!password)return res.status(400).json({error:'Username and password are required'});const u=db.prepare('SELECT * FROM users WHERE lower(username)=lower(?)').get(username);if(!u||!bcrypt.compareSync(password,u.password))return res.status(401).json({error:'Invalid username or password'});establishSession(req,res,u.id,err=>err?res.status(500).json({error:'Could not create session'}):res.json({ok:true,user:safeUser(u)}));});
app.post('/api/logout',(req,res)=>{const finish=err=>{res.clearCookie('liweeitax.sid',{httpOnly:true,sameSite:'lax',secure:process.env.NODE_ENV==='production'});res.json({ok:!err})};if(!req.session)return finish(null);req.session.destroy(finish)});

function feedRows(me,limit=100){return db.prepare(`SELECT p.*,u.username,u.avatar,u.verified,
(SELECT count(*) FROM likes l WHERE l.post_id=p.id) likes,
(SELECT count(*) FROM comments c WHERE c.post_id=p.id) comments,
(SELECT count(*) FROM saves s WHERE s.post_id=p.id) saves,
(SELECT count(*) FROM likes l2 WHERE l2.post_id=p.id AND l2.user_id=?) liked,
(SELECT count(*) FROM saves s2 WHERE s2.post_id=p.id AND s2.user_id=?) saved
FROM posts p JOIN users u ON u.id=p.user_id
WHERE NOT EXISTS(SELECT 1 FROM blocks b WHERE b.blocker_id=? AND b.blocked_id=p.user_id)
AND NOT EXISTS(SELECT 1 FROM mutes m WHERE m.muter_id=? AND m.muted_id=p.user_id)
ORDER BY p.created_at DESC LIMIT ?`).all(me,me,me,me,limit)}
app.get('/api/feed',(req,res)=>res.json(feedRows(req.session.userId||0)));
app.post('/api/posts',auth,upload.single('media'),(req,res)=>{const content=cleanText(req.body.content,3000),music=cleanText(req.body.music,200);if(!content&&!req.file)return res.status(400).json({error:'Write something or attach media'});const media=req.file?'/uploads/'+path.basename(req.file.filename):'';const type=req.file?(req.file.mimetype.startsWith('video')?'video':'image'):'';const r=db.prepare('INSERT INTO posts(user_id,content,media,media_type,music) VALUES(?,?,?,?,?)').run(req.session.userId,content,media,type,music);syncHashtags(r.lastInsertRowid,content);db.prepare('UPDATE users SET xp=xp+10,level=1+(xp+10)/100 WHERE id=?').run(req.session.userId);res.json({id:r.lastInsertRowid})});
app.post('/api/posts/:id/view',(req,res)=>{const id=Number(req.params.id);if(!Number.isInteger(id))return res.status(400).json({error:'Bad id'});const key=req.session.userId?'u:'+req.session.userId:'s:'+String(req.headers['x-forwarded-for']||req.ip||'').slice(0,80);const recent=db.prepare("SELECT id FROM post_views WHERE post_id=? AND session_key=? AND created_at>datetime('now','-10 minutes') LIMIT 1").get(id,key);if(!recent){db.prepare('INSERT INTO post_views(post_id,user_id,session_key) VALUES(?,?,?)').run(id,req.session.userId||null,key);db.prepare('UPDATE posts SET views=views+1 WHERE id=?').run(id)}res.json({ok:true,counted:!recent})});
app.post('/api/posts/:id/like',auth,(req,res)=>{const id=Number(req.params.id),ex=db.prepare('SELECT 1 FROM likes WHERE user_id=? AND post_id=?').get(req.session.userId,id);if(ex)db.prepare('DELETE FROM likes WHERE user_id=? AND post_id=?').run(req.session.userId,id);else{db.prepare('INSERT OR IGNORE INTO likes VALUES(?,?)').run(req.session.userId,id);const p=db.prepare('SELECT user_id FROM posts WHERE id=?').get(id);if(p&&p.user_id!==req.session.userId)notify(p.user_id,'like','Someone liked your post ❤️')}res.json({liked:!ex})});
app.post('/api/posts/:id/save',auth,(req,res)=>{const id=Number(req.params.id),ex=db.prepare('SELECT 1 FROM saves WHERE user_id=? AND post_id=?').get(req.session.userId,id);if(ex)db.prepare('DELETE FROM saves WHERE user_id=? AND post_id=?').run(req.session.userId,id);else db.prepare('INSERT OR IGNORE INTO saves VALUES(?,?)').run(req.session.userId,id);res.json({saved:!ex})});
app.delete('/api/posts/:id',auth,(req,res)=>{const p=db.prepare('SELECT * FROM posts WHERE id=?').get(req.params.id);if(!p)return res.status(404).json({error:'Post not found'});if(p.user_id!==req.session.userId)return res.status(403).json({error:'Only the owner can delete this post'});db.prepare('DELETE FROM posts WHERE id=?').run(p.id);if(p.media){const f=path.join(UPLOADS,path.basename(p.media));try{fs.unlinkSync(f)}catch{}}res.json({ok:true})});

app.get('/api/posts/:id/comments',(req,res)=>res.json(db.prepare('SELECT c.*,u.username,u.avatar,u.verified FROM comments c JOIN users u ON u.id=c.user_id WHERE c.post_id=? ORDER BY c.pinned DESC,c.created_at ASC').all(req.params.id)));
app.post('/api/posts/:id/comments',auth,(req,res)=>{const content=cleanText(req.body.content,1000);if(!content)return res.status(400).json({error:'Comment is empty'});const r=db.prepare('INSERT INTO comments(user_id,post_id,parent_id,content) VALUES(?,?,?,?)').run(req.session.userId,req.params.id,req.body.parent_id?Number(req.body.parent_id):null,content);const p=db.prepare('SELECT user_id FROM posts WHERE id=?').get(req.params.id);if(p&&p.user_id!==req.session.userId)notify(p.user_id,'comment','Someone commented on your post 💬');res.json({id:r.lastInsertRowid})});
app.post('/api/comments/:id/pin',auth,(req,res)=>{const c=db.prepare('SELECT * FROM comments WHERE id=?').get(req.params.id);if(!c)return res.status(404).json({error:'Comment not found'});const post=db.prepare('SELECT user_id FROM posts WHERE id=?').get(c.post_id);if(!post||post.user_id!==req.session.userId)return res.status(403).json({error:'Only the post owner can pin comments'});db.prepare('UPDATE comments SET pinned=0 WHERE post_id=?').run(c.post_id);db.prepare('UPDATE comments SET pinned=1 WHERE id=?').run(c.id);res.json({ok:true})});
app.delete('/api/comments/:id',auth,(req,res)=>{const c=db.prepare('SELECT * FROM comments WHERE id=?').get(req.params.id);if(!c)return res.status(404).json({error:'Comment not found'});const p=db.prepare('SELECT user_id FROM posts WHERE id=?').get(c.post_id);if(c.user_id!==req.session.userId&&(!p||p.user_id!==req.session.userId))return res.status(403).json({error:'Not allowed'});db.prepare('DELETE FROM comments WHERE id=?').run(c.id);res.json({ok:true})});

app.post('/api/users/:id/follow',auth,(req,res)=>{const id=Number(req.params.id);if(id===req.session.userId)return res.status(400).json({error:'Cannot follow yourself'});if(!db.prepare('SELECT id FROM users WHERE id=?').get(id))return res.status(404).json({error:'User not found'});if(isBlocked(req.session.userId,id)||isBlocked(id,req.session.userId))return res.status(403).json({error:'This action is unavailable'});const ex=db.prepare('SELECT 1 FROM follows WHERE follower_id=? AND following_id=?').get(req.session.userId,id);if(ex)db.prepare('DELETE FROM follows WHERE follower_id=? AND following_id=?').run(req.session.userId,id);else{db.prepare('INSERT OR IGNORE INTO follows VALUES(?,?)').run(req.session.userId,id);notify(id,'follow','Someone followed you 👤')}res.json({following:!ex})});
app.get('/api/search',(req,res)=>{const raw=cleanText(req.query.q,80);if(!raw)return res.json([]);const q='%'+raw.replace(/[%_]/g,'')+'%';const users=db.prepare('SELECT id,username,bio,avatar,verified FROM users WHERE lower(username) LIKE lower(?) OR lower(bio) LIKE lower(?) LIMIT 30').all(q,q);const posts=db.prepare('SELECT p.id,p.content,p.media,p.media_type,p.views,u.username,u.avatar,u.verified FROM posts p JOIN users u ON u.id=p.user_id WHERE lower(p.content) LIKE lower(?) ORDER BY p.created_at DESC LIMIT 30').all(q);res.json({users,posts})});
app.get('/api/explore',(req,res)=>res.json(db.prepare(`SELECT p.*,u.username,u.avatar,u.verified,(SELECT count(*) FROM likes WHERE post_id=p.id) likes,(SELECT count(*) FROM comments WHERE post_id=p.id) comments FROM posts p JOIN users u ON u.id=p.user_id WHERE NOT EXISTS(SELECT 1 FROM blocks b WHERE b.blocker_id=? AND b.blocked_id=p.user_id) ORDER BY ((SELECT count(*) FROM likes WHERE post_id=p.id)*0.5+p.views*0.3+(SELECT count(*) FROM comments WHERE post_id=p.id)*0.2) DESC,p.created_at DESC LIMIT 50`).all(req.session.userId||0)));

app.get('/api/profile/:username',(req,res)=>{const u=db.prepare('SELECT * FROM users WHERE lower(username)=lower(?)').get(req.params.username);if(!u)return res.status(404).json({error:'Not found'});if(req.session.userId&&isBlocked(req.session.userId,u.id))return res.status(404).json({error:'Not found'});const followers=db.prepare('SELECT count(*) c FROM follows WHERE following_id=?').get(u.id).c;const following=db.prepare('SELECT count(*) c FROM follows WHERE follower_id=?').get(u.id).c;const isFollowing=!!(req.session.userId&&db.prepare('SELECT 1 FROM follows WHERE follower_id=? AND following_id=?').get(req.session.userId,u.id));const stickers=db.prepare('SELECT ps.*,u.username FROM profile_stickers ps JOIN users u ON u.id=ps.sender_id WHERE ps.owner_id=? ORDER BY ps.created_at DESC LIMIT 30').all(u.id);const privateView=u.private&&u.id!==(req.session.userId||0)&&!isFollowing;const posts=privateView?[]:db.prepare('SELECT p.*,(SELECT count(*) FROM likes WHERE post_id=p.id) likes,(SELECT count(*) FROM comments WHERE post_id=p.id) comments FROM posts p WHERE user_id=? ORDER BY created_at DESC').all(u.id);res.json({user:safeUser(u),followers,following,isFollowing,privateLocked:privateView,stickers,posts})});
app.post('/api/profile/:id/sticker',auth,(req,res)=>{const owner=Number(req.params.id),sticker=cleanText(req.body.sticker,12);if(owner===req.session.userId)return res.status(400).json({error:'You cannot send a sticker to yourself'});if(!sticker||!db.prepare('SELECT id FROM users WHERE id=?').get(owner))return res.status(404).json({error:'User not found'});db.prepare('INSERT INTO profile_stickers(owner_id,sender_id,sticker) VALUES(?,?,?)').run(owner,req.session.userId,sticker);notify(owner,'sticker','Someone sent you a profile sticker '+sticker);res.json({ok:true})});
app.get('/api/saved',auth,(req,res)=>res.json(db.prepare('SELECT p.*,u.username,u.avatar,u.verified FROM posts p JOIN saves s ON s.post_id=p.id JOIN users u ON u.id=p.user_id WHERE s.user_id=? ORDER BY p.created_at DESC').all(req.session.userId)));
app.post('/api/profile',auth,upload.fields([{name:'avatar',maxCount:1},{name:'cover',maxCount:1}]),(req,res)=>{let bio=cleanText(req.body.bio,300),website=cleanText(req.body.website,200);let u=db.prepare('SELECT * FROM users WHERE id=?').get(req.session.userId);let avatar=u.avatar,cover=u.cover;if(req.files?.avatar?.[0])avatar='/uploads/'+path.basename(req.files.avatar[0].filename);if(req.files?.cover?.[0])cover='/uploads/'+path.basename(req.files.cover[0].filename);const priv=String(req.body.private)==='1'?1:0;db.prepare('UPDATE users SET bio=?,website=?,private=?,avatar=?,cover=? WHERE id=?').run(bio,website,priv,avatar,cover,req.session.userId);res.json({ok:true})});

app.get('/api/settings',auth,(req,res)=>{const u=db.prepare('SELECT id,username,bio,website,private FROM users WHERE id=?').get(req.session.userId);res.json({user:{...u,private:!!u.private}})});
app.post('/api/settings',auth,(req,res)=>{const bio=cleanText(req.body.bio,300),website=cleanText(req.body.website,200),priv=req.body.private?1:0;db.prepare('UPDATE users SET bio=?,website=?,private=? WHERE id=?').run(bio,website,priv,req.session.userId);res.json({ok:true})});
app.get('/api/notifications',auth,(req,res)=>res.json(db.prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 100').all(req.session.userId)));
app.post('/api/notifications/read',auth,(req,res)=>{db.prepare('UPDATE notifications SET read=1 WHERE user_id=?').run(req.session.userId);res.json({ok:true})});
app.get('/api/notifications/unread-count',auth,(req,res)=>res.json({count:db.prepare('SELECT count(*) c FROM notifications WHERE user_id=? AND read=0').get(req.session.userId).c}));

app.post('/api/block/:id',auth,(req,res)=>{const id=Number(req.params.id);if(id===req.session.userId)return res.status(400).json({error:'Invalid user'});const ex=db.prepare('SELECT 1 FROM blocks WHERE blocker_id=? AND blocked_id=?').get(req.session.userId,id);if(ex)db.prepare('DELETE FROM blocks WHERE blocker_id=? AND blocked_id=?').run(req.session.userId,id);else{db.prepare('INSERT OR IGNORE INTO blocks VALUES(?,?)').run(req.session.userId,id);db.prepare('DELETE FROM follows WHERE follower_id=? AND following_id=?').run(req.session.userId,id);db.prepare('DELETE FROM follows WHERE follower_id=? AND following_id=?').run(id,req.session.userId)}res.json({blocked:!ex})});
app.post('/api/mute/:id',auth,(req,res)=>{const id=Number(req.params.id);const ex=db.prepare('SELECT 1 FROM mutes WHERE muter_id=? AND muted_id=?').get(req.session.userId,id);if(ex)db.prepare('DELETE FROM mutes WHERE muter_id=? AND muted_id=?').run(req.session.userId,id);else db.prepare('INSERT OR IGNORE INTO mutes VALUES(?,?)').run(req.session.userId,id);res.json({muted:!ex})});
app.get('/api/relationship/:id',auth,(req,res)=>res.json({blocked:!!db.prepare('SELECT 1 FROM blocks WHERE blocker_id=? AND blocked_id=?').get(req.session.userId,req.params.id),muted:!!db.prepare('SELECT 1 FROM mutes WHERE muter_id=? AND muted_id=?').get(req.session.userId,req.params.id)}));

app.post('/api/drafts',auth,(req,res)=>{const id=req.body.id?Number(req.body.id):null,content=cleanText(req.body.content,3000),music=cleanText(req.body.music,200);if(id){db.prepare('UPDATE drafts SET content=?,music=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND user_id=?').run(content,music,id,req.session.userId);return res.json({id})}const r=db.prepare('INSERT INTO drafts(user_id,content,music) VALUES(?,?,?)').run(req.session.userId,content,music);res.json({id:r.lastInsertRowid})});
app.get('/api/drafts',auth,(req,res)=>res.json(db.prepare('SELECT * FROM drafts WHERE user_id=? ORDER BY updated_at DESC').all(req.session.userId)));
app.delete('/api/drafts/:id',auth,(req,res)=>{db.prepare('DELETE FROM drafts WHERE id=? AND user_id=?').run(req.params.id,req.session.userId);res.json({ok:true})});

app.get('/api/chats/:id',auth,(req,res)=>{const id=Number(req.params.id);if(isBlocked(req.session.userId,id)||isBlocked(id,req.session.userId))return res.status(403).json({error:'Chat unavailable'});db.prepare('UPDATE messages SET seen=1 WHERE sender_id=? AND receiver_id=?').run(id,req.session.userId);res.json(db.prepare('SELECT m.*,u.username FROM messages m JOIN users u ON u.id=m.sender_id WHERE (sender_id=? AND receiver_id=?) OR (sender_id=? AND receiver_id=?) ORDER BY m.created_at ASC LIMIT 200').all(req.session.userId,id,id,req.session.userId))});
app.post('/api/chats/:id',auth,upload.single('media'),(req,res)=>{const id=Number(req.params.id);if(!db.prepare('SELECT id FROM users WHERE id=?').get(id))return res.status(404).json({error:'User not found'});if(isBlocked(req.session.userId,id)||isBlocked(id,req.session.userId))return res.status(403).json({error:'Chat unavailable'});const content=cleanText(req.body.content,3000),media=req.file?'/uploads/'+path.basename(req.file.filename):'';if(!content&&!media)return res.status(400).json({error:'Empty message'});const r=db.prepare('INSERT INTO messages(sender_id,receiver_id,content,media) VALUES(?,?,?,?)').run(req.session.userId,id,content,media);const streak=updateChatStreak(req.session.userId,id);notify(id,'message',`You received a message ✉️ • ${streak}🔥 streak`);res.json({id:r.lastInsertRowid,streak})});

app.post('/api/report',auth,(req,res)=>{const target=cleanText(req.body.target_type,30),reason=cleanText(req.body.reason,500),id=Number(req.body.target_id);if(!target||!id||!reason)return res.status(400).json({error:'Missing report details'});db.prepare('INSERT INTO reports(reporter_id,target_type,target_id,reason) VALUES(?,?,?,?)').run(req.session.userId,target,id,reason);res.json({ok:true})});
app.get('/api/admin/users',auth,(req,res)=>{const meUser=db.prepare('SELECT username FROM users WHERE id=?').get(req.session.userId);if(!meUser||meUser.username.toLowerCase()!=='admin')return res.status(403).json({error:'Admin only'});res.json(db.prepare('SELECT id,username,bio,verified,verification_label,created_at FROM users ORDER BY created_at DESC LIMIT 200').all())});
app.post('/api/admin/verify/:id',auth,(req,res)=>{const meUser=db.prepare('SELECT username FROM users WHERE id=?').get(req.session.userId);if(!meUser||meUser.username.toLowerCase()!=='admin')return res.status(403).json({error:'Admin only'});const id=Number(req.params.id);const verified=Boolean(req.body.verified);const label=cleanText(req.body.label||'Verified account',80)||'Verified account';const r=db.prepare('UPDATE users SET verified=?,verification_label=? WHERE id=?').run(verified?1:0,label,id);if(!r.changes)return res.status(404).json({error:'User not found'});res.json({ok:true,verified:verified,label})});
app.get('/api/admin/stats',auth,(req,res)=>{const u=db.prepare('SELECT username FROM users WHERE id=?').get(req.session.userId);if(!u||u.username.toLowerCase()!=='admin')return res.status(403).json({error:'Admin only'});res.json({users:db.prepare('SELECT count(*) c FROM users').get().c,posts:db.prepare('SELECT count(*) c FROM posts').get().c,comments:db.prepare('SELECT count(*) c FROM comments').get().c,messages:db.prepare('SELECT count(*) c FROM messages').get().c,reports:db.prepare('SELECT count(*) c FROM reports').get().c,likes:db.prepare('SELECT count(*) c FROM likes').get().c})});


