// V11 feature platform: capability registry + a set of concrete social features.
app.get('/api/features',(req,res)=>{
  const catalog=FEATURE_CATALOG;
  res.json({version:'11.0',count:catalog.length,features:catalog});
});
app.post('/api/features/use',auth,(req,res)=>{
  const key=cleanText(req.body.feature_key,120); if(!key)return res.status(400).json({error:'feature_key required'});
  const r=db.prepare(`INSERT INTO feature_usage(user_id,feature_key,count,last_used) VALUES(?,?,1,CURRENT_TIMESTAMP) ON CONFLICT(user_id,feature_key) DO UPDATE SET count=count+1,last_used=CURRENT_TIMESTAMP`).run(req.session.userId,key);
  res.json({ok:true});
});
app.get('/api/overview',auth,(req,res)=>{
  const uid=req.session.userId;
  const stats={posts:db.prepare('SELECT count(*) c FROM posts WHERE user_id=?').get(uid).c,followers:db.prepare('SELECT count(*) c FROM follows WHERE following_id=?').get(uid).c,following:db.prepare('SELECT count(*) c FROM follows WHERE follower_id=?').get(uid).c,likes:db.prepare('SELECT count(*) c FROM likes l JOIN posts p ON p.id=l.post_id WHERE p.user_id=?').get(uid).c,views:db.prepare('SELECT coalesce(sum(views),0) c FROM posts WHERE user_id=?').get(uid).c,saved:db.prepare('SELECT count(*) c FROM saves WHERE user_id=?').get(uid).c};
  res.json(stats);
});
app.get('/api/mentions',auth,(req,res)=>res.json(db.prepare(`SELECT m.*,u.username,p.content FROM mentions m JOIN users u ON u.id=m.mentioned_user_id LEFT JOIN posts p ON p.id=m.post_id WHERE m.mentioned_user_id=? ORDER BY m.created_at DESC LIMIT 100`).all(req.session.userId)));
app.post('/api/posts/:id/poll',auth,(req,res)=>{
  const post=db.prepare('SELECT id,user_id FROM posts WHERE id=?').get(req.params.id); if(!post||post.user_id!==req.session.userId)return res.status(403).json({error:'Only the post owner can add a poll'});
  const q=cleanText(req.body.question,240); const opts=Array.isArray(req.body.options)?req.body.options.map(x=>cleanText(x,120)).filter(Boolean).slice(2,8):[]; if(!q||opts.length<2)return res.status(400).json({error:'Poll needs a question and at least two options'});
  const r=db.prepare('INSERT OR REPLACE INTO post_polls(post_id,question,options_json,expires_at) VALUES(?,?,?,?)').run(post.id,q,JSON.stringify(opts),req.body.expires_at||null); res.json({ok:true,id:r.lastInsertRowid});
});
app.get('/api/posts/:id/poll',(req,res)=>{const p=db.prepare('SELECT * FROM post_polls WHERE post_id=?').get(req.params.id);if(!p)return res.status(404).json({error:'No poll'});const votes=db.prepare('SELECT option_index,count(*) c FROM poll_votes WHERE poll_id=? GROUP BY option_index').all(p.id);res.json({id:p.id,question:p.question,options:JSON.parse(p.options_json),votes});});
app.post('/api/polls/:id/vote',auth,(req,res)=>{const poll=db.prepare('SELECT * FROM post_polls WHERE id=?').get(req.params.id);if(!poll)return res.status(404).json({error:'Poll not found'});const i=Number(req.body.option_index);const opts=JSON.parse(poll.options_json);if(!Number.isInteger(i)||i<0||i>=opts.length)return res.status(400).json({error:'Invalid option'});db.prepare('INSERT OR REPLACE INTO poll_votes(poll_id,user_id,option_index) VALUES(?,?,?)').run(poll.id,req.session.userId,i);res.json({ok:true});});
app.post('/api/scheduled-posts',auth,(req,res)=>{const content=cleanText(req.body.content,3000),at=cleanText(req.body.publish_at,40);if(!content||!at)return res.status(400).json({error:'Content and publish_at required'});const d=new Date(at);if(Number.isNaN(d.getTime())||d.getTime()<=Date.now())return res.status(400).json({error:'publish_at must be a future date'});const r=db.prepare('INSERT INTO scheduled_posts(user_id,content,publish_at) VALUES(?,?,?)').run(req.session.userId,content,d.toISOString());res.json({id:r.lastInsertRowid,status:'scheduled'});});
app.get('/api/scheduled-posts',auth,(req,res)=>res.json(db.prepare('SELECT * FROM scheduled_posts WHERE user_id=? ORDER BY publish_at').all(req.session.userId)));
app.delete('/api/scheduled-posts/:id',auth,(req,res)=>{db.prepare("DELETE FROM scheduled_posts WHERE id=? AND user_id=? AND status='scheduled'").run(req.params.id,req.session.userId);res.json({ok:true});});
app.get('/api/preferences',auth,(req,res)=>{let p=db.prepare('SELECT * FROM notification_preferences WHERE user_id=?').get(req.session.userId);if(!p){db.prepare('INSERT OR IGNORE INTO notification_preferences(user_id) VALUES(?)').run(req.session.userId);p=db.prepare('SELECT * FROM notification_preferences WHERE user_id=?').get(req.session.userId)}res.json(p);});
app.post('/api/preferences',auth,(req,res)=>{const fields=['likes','comments','follows','messages','mentions','stories','reposts','streaks'];db.prepare(`INSERT INTO notification_preferences(user_id,${fields.join(',')}) VALUES(?,${fields.map(()=>'?').join(',')}) ON CONFLICT(user_id) DO UPDATE SET ${fields.map(f=>f+'=excluded.'+f).join(',')}`).run(req.session.userId,...fields.map(f=>req.body[f]?1:0));res.json({ok:true});});
app.post('/api/hidden-words',auth,(req,res)=>{const w=cleanText(req.body.word,60).toLowerCase();if(!w)return res.status(400).json({error:'word required'});db.prepare('INSERT OR IGNORE INTO hidden_words(user_id,word) VALUES(?,?)').run(req.session.userId,w);res.json({ok:true});});
app.get('/api/hidden-words',auth,(req,res)=>res.json(db.prepare('SELECT word FROM hidden_words WHERE user_id=? ORDER BY word').all(req.session.userId).map(x=>x.word)));
app.delete('/api/hidden-words/:word',auth,(req,res)=>{db.prepare('DELETE FROM hidden_words WHERE user_id=? AND word=?').run(req.session.userId,String(req.params.word).toLowerCase());res.json({ok:true});});
app.post('/api/profile/username',auth,(req,res)=>{const u=cleanText(req.body.username,30).replace(/^@/,'').toLowerCase();if(!/^[a-z0-9_.]{3,30}$/.test(u))return res.status(400).json({error:'Username must be 3-30 characters: letters, numbers, _ or .'});const exists=db.prepare('SELECT id FROM users WHERE lower(username)=lower(?) AND id<>?').get(u,req.session.userId);if(exists)return res.status(409).json({error:'Username already taken'});db.prepare('UPDATE users SET username=? WHERE id=?').run(u,req.session.userId);res.json({ok:true,username:u});});
app.post('/api/profile/bio',auth,(req,res)=>{db.prepare('UPDATE users SET bio=? WHERE id=?').run(cleanText(req.body.bio,500),req.session.userId);res.json({ok:true});});
app.get('/api/admin/reports',auth,(req,res)=>{const u=db.prepare('SELECT username FROM users WHERE id=?').get(req.session.userId);if(!u||u.username.toLowerCase()!=='admin')return res.status(403).json({error:'Admin only'});res.json({reports:db.prepare('SELECT * FROM reports ORDER BY created_at DESC LIMIT 300').all(),postReports:db.prepare('SELECT * FROM post_reports ORDER BY created_at DESC LIMIT 300').all()});});
app.post('/api/admin/posts/:id/delete',auth,(req,res)=>{const u=db.prepare('SELECT username FROM users WHERE id=?').get(req.session.userId);if(!u||u.username.toLowerCase()!=='admin')return res.status(403).json({error:'Admin only'});db.prepare('DELETE FROM posts WHERE id=?').run(req.params.id);res.json({ok:true});});

app.use((err,req,res,next)=>{if(err instanceof multer.MulterError)return res.status(400).json({error:'Upload error: '+err.code});console.error(err);res.status(500).json({error:'Server error'})});
app.get('/health',(req,res)=>res.status(200).json({status:'ok',service:'liweeitax'}));
app.get('*',(req,res)=>res.sendFile(path.join(ROOT,'public','index.html')));
app.listen(PORT,'0.0.0.0',()=>console.log('Liweeitax Mega Plus running on '+PORT));
